<template><div class="page-container"><PageHeader>流程配置<template #desc>配置业务审批节点、流转顺序及每一步审批人；每次保存都会发布新版本</template><template #actions><el-button type="primary" :disabled="availableTypes.length===0" @click="openNew"><el-icon><Plus/></el-icon>&nbsp;新增流程</el-button></template></PageHeader><el-alert title="流程按版本发布：新配置只影响发布后的申请，运行中的单据继续使用发起时版本。" type="info" :closable="false" show-icon style="margin-bottom:16px"/><el-card v-for="flow in rows" :key="flow.id" class="flow-card" shadow="never"><div class="flow-head"><div><b>{{flow.name}}</b><el-tag size="small" type="primary">{{businessLabel(flow.businessType)}}</el-tag><el-tag size="small" effect="plain">V{{flow.version}}</el-tag><el-tag size="small" type="success">已接入运行</el-tag></div><div><el-tag :type="flow.enabled?'success':'info'">{{flow.enabled?'启用':'停用'}}</el-tag><el-button link type="primary" @click="open(flow)">发布新版本</el-button></div></div><div class="flow-line"><template v-for="(node,i) in flow.nodes" :key="node.id"><div class="node"><span>{{i+1}}</span><div><b>{{node.name}}</b><small>{{node.approverType==='ROLE'?'角色':'用户'}}：{{node.approverLabel}}</small></div></div><el-icon v-if="i<flow.nodes.length-1" class="arrow"><Right/></el-icon></template></div></el-card><el-empty v-if="rows.length===0" description="暂无流程配置"/>
<el-dialog v-model="visible" :title="editing?'配置审批流程':'新增审批流程'" :width="dialogWidth" destroy-on-close><el-form label-position="top"><div class="base-form"><el-form-item label="业务类型"><el-select v-model="form.businessType" :disabled="!!editing" style="width:100%"><el-option v-for="x in businessTypes" :key="x.value" :label="x.label" :value="x.value" :disabled="configuredTypes.includes(x.value)"/></el-select></el-form-item><el-form-item label="流程名称"><el-input v-model="form.name" maxlength="64" placeholder="请输入便于识别的流程名称"/></el-form-item><el-form-item label="启用状态"><div class="switch-line"><el-switch v-model="form.enabled"/><span>{{form.enabled?'新申请将按此流程流转':'停用后不再按此配置流转'}}</span></div></el-form-item></div><div v-if="form.businessType==='OUTBOUND'" class="condition-panel"><div class="condition-head"><div><b>审批触发条件</b><small>未命中条件的领用申请由系统直接放行</small></div><el-radio-group v-model="form.triggerMode" size="small"><el-radio-button value="ALWAYS">始终审批</el-radio-button><el-radio-button value="ANY">任一满足</el-radio-button><el-radio-button value="ALL">全部满足</el-radio-button></el-radio-group></div><div v-if="form.triggerMode!=='ALWAYS'" class="condition-grid"><el-form-item label="备件分类"><el-select v-model="form.triggerCategories" multiple filterable allow-create default-first-option clearable placeholder="选择或输入分类" style="width:100%"/></el-form-item><el-form-item label="领用总数量不少于"><el-input-number v-model="form.minTotalQty" :min="0" controls-position="right" style="width:100%"/></el-form-item><el-form-item label="参考总金额不少于"><el-input-number v-model="form.minTotalAmount" :min="0" :precision="2" controls-position="right" style="width:100%"/><small class="condition-tip">金额按备件主数据的参考单价计算</small></el-form-item></div></div><div class="section-title"><div><b>审批节点</b><small>从上到下依次执行，末级通过后自动执行业务</small></div><el-button plain type="primary" size="small" @click="addNode"><el-icon><Plus/></el-icon>&nbsp;增加节点</el-button></div><div class="node-editor"><div v-for="(node,i) in form.nodes" :key="i" class="node-row"><div class="node-order"><span class="seq">{{i+1}}</span><small>第 {{i+1}} 级</small></div><div class="node-fields"><el-form-item label="节点名称"><el-input v-model="node.name" placeholder="例如：部门负责人审批"/></el-form-item><el-form-item label="审批方式"><el-select v-model="node.approverType" style="width:100%" @change="node.approverValue='' "><el-option label="按角色审批" value="ROLE"/><el-option label="指定用户审批" value="USER"/></el-select></el-form-item><el-form-item label="审批人"><el-select v-model="node.approverValue" filterable placeholder="请选择" style="width:100%"><el-option v-for="x in options(node.approverType)" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></div><div class="node-actions"><el-button text circle :disabled="i===0" title="上移" @click="moveNode(i,-1)"><el-icon><ArrowUp/></el-icon></el-button><el-button text circle :disabled="i===form.nodes.length-1" title="下移" @click="moveNode(i,1)"><el-icon><ArrowDown/></el-icon></el-button><el-button text circle type="danger" :disabled="form.nodes.length===1" title="删除" @click="removeNode(i)"><el-icon><Delete/></el-icon></el-button></div></div></div></el-form><template #footer><div class="dialog-footer"><span>共 {{form.nodes.length}} 个审批节点</span><div><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存并应用</el-button></div></div></template></el-dialog></div></template>
<script setup>
import { ref, reactive, computed, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import api from '@/api/workflows'
import { useMobile } from '@/composables/useMobile'
const rows=ref([]), visible=ref(false), saving=ref(false), editing=ref(null)
const {isMobile}=useMobile(), dialogWidth=computed(()=>isMobile.value?'95%':'880px')
const candidates=reactive({roles:[],users:[]})
const form=reactive({businessType:'OUTBOUND',name:'',enabled:true,triggerMode:'ALWAYS',triggerCategories:[],minTotalQty:null,minTotalAmount:null,nodes:[]})
const businessTypes=[{value:'OUTBOUND',label:'领用申请'},{value:'RETURN',label:'退库确认'},{value:'SCRAP',label:'报废申请'},{value:'STOCKTAKE_DIFF',label:'盘点差异复核'}]
const businessLabel=t=>businessTypes.find(x=>x.value===t)?.label||t
const configuredTypes=computed(()=>rows.value.map(x=>x.businessType))
const availableTypes=computed(()=>businessTypes.filter(x=>!configuredTypes.value.includes(x.value)))
const options=t=>t==='ROLE'?candidates.roles:candidates.users
async function load(){const [flows,people]=await Promise.all([api.list(),api.candidates()]);rows.value=flows;Object.assign(candidates,people)}
function open(x){editing.value=x;Object.assign(form,{businessType:x.businessType,name:x.name,enabled:x.enabled,triggerMode:x.triggerMode||'ALWAYS',triggerCategories:x.triggerCategories||[],minTotalQty:x.minTotalQty??null,minTotalAmount:x.minTotalAmount??null,nodes:x.nodes.map(n=>({name:n.name,approverType:n.approverType,approverValue:n.approverValue}))});visible.value=true}
function openNew(){const type=availableTypes.value[0];if(!type)return;editing.value=null;Object.assign(form,{businessType:type.value,name:`${type.label}流程`,enabled:true,triggerMode:'ALWAYS',triggerCategories:[],minTotalQty:null,minTotalAmount:null,nodes:[{name:'审批',approverType:'ROLE',approverValue:''}]});visible.value=true}
function addNode(){form.nodes.push({name:`审批节点${form.nodes.length+1}`,approverType:'ROLE',approverValue:''})}
function removeNode(i){form.nodes.splice(i,1)}
function moveNode(i,step){const target=i+step;if(target<0||target>=form.nodes.length)return;const current=form.nodes[i];form.nodes.splice(i,1);form.nodes.splice(target,0,current)}
async function save(){if(!form.businessType||!form.name.trim()||form.nodes.some(n=>!n.name.trim()||!n.approverValue))return ElMessage.warning('请完整填写流程和审批节点');if(form.businessType==='OUTBOUND'&&form.triggerMode!=='ALWAYS'&&!form.triggerCategories.length&&form.minTotalQty==null&&form.minTotalAmount==null)return ElMessage.warning('请至少配置一个审批触发条件');saving.value=true;try{const payload={...form,nodes:form.nodes.map((n,i)=>({...n,sequence:i+1}))};const saved=editing.value?await api.update(editing.value.id,payload):await api.create(payload);ElMessage.success(`流程 V${saved.version} 已发布`);visible.value=false;await load()}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped lang="scss">.flow-card{margin-bottom:14px;transition:.2s}.flow-card:hover{border-color:#bae6fd!important;box-shadow:0 10px 28px rgba(14,165,233,.08)}.flow-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.flow-head>div{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.flow-head b{font-size:16px;color:#18314f}.flow-line{display:flex;align-items:center;gap:12px;margin-top:20px;overflow:auto;padding:4px 2px 8px}.node{min-width:190px;display:flex;align-items:center;gap:10px;padding:13px;border:1px solid #dbe8f5;background:linear-gradient(145deg,#f8fbff,#fff);border-radius:11px}.node>span,.seq{width:28px;height:28px;display:grid;place-items:center;border-radius:50%;background:linear-gradient(135deg,#1677ff,#38bdf8);color:#fff;font-size:12px;flex:none;box-shadow:0 4px 10px rgba(22,119,255,.2)}.node div{display:flex;flex-direction:column;gap:4px}.node small{color:#64748b}.arrow{color:#38bdf8}.base-form{display:grid;grid-template-columns:1fr 1.5fr .8fr;gap:14px}.switch-line{height:32px;display:flex;align-items:center;gap:9px;color:#64748b;font-size:12px}.section-title{display:flex;align-items:end;justify-content:space-between;border-top:1px solid #e8eef5;padding-top:17px;margin:2px 0 12px}.section-title b,.section-title small{display:block}.section-title small{font-size:12px;color:#8492a6;margin-top:4px}.node-editor{display:flex;flex-direction:column;gap:10px;max-height:48vh;overflow:auto;padding-right:3px}.node-row{display:grid;grid-template-columns:72px 1fr 38px;align-items:center;gap:12px;padding:14px;border:1px solid #e3eaf3;border-radius:12px;background:#f9fbfd}.node-order{display:flex;flex-direction:column;align-items:center;gap:5px;color:#8492a6}.node-order small{font-size:11px}.node-fields{display:grid;grid-template-columns:1.2fr 1fr 1.2fr;gap:10px}.node-fields :deep(.el-form-item){margin-bottom:0}.node-fields :deep(.el-form-item__label){font-size:12px;color:#64748b;padding-bottom:4px}.node-actions{display:flex;flex-direction:column;gap:2px}.node-actions .el-button{margin:0}.dialog-footer{display:flex;align-items:center;justify-content:space-between}.dialog-footer>span{font-size:12px;color:#8492a6}
.condition-panel{margin:2px 0 18px;padding:15px;border:1px solid #dbeafe;border-radius:12px;background:linear-gradient(135deg,#f5faff,#fbfdff)}.condition-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.condition-head b,.condition-head small{display:block}.condition-head small,.condition-tip{font-size:12px;color:#8492a6;margin-top:4px}.condition-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:12px;margin-top:14px}.condition-grid :deep(.el-form-item){margin-bottom:0}@media(max-width:767px){.condition-head{align-items:flex-start;flex-direction:column}.condition-grid{grid-template-columns:1fr}.flow-head{align-items:flex-start}.flow-head>div:last-child{justify-content:flex-end}.flow-line{align-items:stretch}.node{min-width:168px}.base-form{grid-template-columns:1fr}.node-row{grid-template-columns:42px 1fr}.node-fields{grid-template-columns:1fr}.node-actions{grid-column:2;flex-direction:row;justify-content:flex-end}.node-editor{max-height:55vh}.dialog-footer>span{display:none}.dialog-footer{justify-content:flex-end}}</style>
